import sqlite3
import json
import traceback

output_path = '/workspace/booking_result.json'

try:
    results = {}
    db_path = '/workspace/world.db'
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    tables = [r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()]
    results['tables'] = tables
    schemas = {}
    for t in tables:
        cols = [(r[1], r[2]) for r in conn.execute(f'PRAGMA table_info({t})').fetchall()]
        schemas[t] = cols
    results['schemas'] = schemas
    try:
        rows = conn.execute("SELECT * FROM flight_bookings WHERE booking_id=?", ('BK-B70889',)).fetchall()
        results['booking'] = [dict(r) for r in rows]
    except Exception as e:
        results['booking_error'] = str(e)
    if results.get('booking'):
        uid = results['booking'][0].get('user_id')
        if uid:
            users = conn.execute("SELECT * FROM users WHERE user_id=?", (uid,)).fetchall()
            results['user'] = [dict(r) for r in users]
    conn.close()
    results['status'] = 'success'
except Exception as e:
    results = {'status': 'error', 'error': str(e), 'traceback': traceback.format_exc()}

with open(output_path, 'w') as f:
    json.dump(results, f, indent=2, default=str)

